package com.alsafa.native4;

import android.app.Activity;import android.app.AlertDialog;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.os.Handler;import android.os.Looper;import android.text.Editable;import android.text.TextWatcher;import android.view.Gravity;import android.view.View;import android.view.ViewGroup;import android.widget.ArrayAdapter;import android.widget.Button;import android.widget.EditText;import android.widget.LinearLayout;import android.widget.Spinner;import android.widget.TextView;import com.alsafa.native4.core.AccountingChoices;import com.alsafa.native4.core.RepairPartStore;import java.util.ArrayList;import com.alsafa.native4.core.Native4BackgroundSync;import com.alsafa.native4.core.Native4Services;
/** Familiar AlSafa repair intake on top of the Native4 accounting core. */
public final class CoreRepairPanelBinder {
 private final Activity a;private final Native4Services services;private final TextView status;private final EditText customer,phone,watch,total,partSearch,partQty;private final Spinner partResults;private final ArrayList<RepairPartStore.SearchResult> partItems=new ArrayList<>();private final Handler handler=new Handler(Looper.getMainLooper());private Runnable partPending;private final Spinner currency,account;private final RepairDeliveryDialog delivery;
 public CoreRepairPanelBinder(Activity a,Native4Services services,TextView status){if(services==null)throw new IllegalArgumentException("Native4Services مطلوب");this.a=a;this.services=services;this.status=status;delivery=new RepairDeliveryDialog(a,services,status);customer=a.findViewById(R.id.repairCustomer);phone=a.findViewById(R.id.repairPhone);watch=a.findViewById(R.id.repairWatch);total=a.findViewById(R.id.repairTotal);partSearch=a.findViewById(R.id.repairPartSearch);partQty=a.findViewById(R.id.repairPartQty);partResults=a.findViewById(R.id.repairPartResults);partQty.setText("1");partSearch.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int af){}public void onTextChanged(CharSequence s,int st,int b,int c){if(partPending!=null)handler.removeCallbacks(partPending);partPending=()->refreshParts();handler.postDelayed(partPending,325);}public void afterTextChanged(Editable e){}});currency=a.findViewById(R.id.repairCurrency);account=a.findViewById(R.id.repairAccount);currency.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,AccountingChoices.CURRENCY_LABELS));account.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"الدفع عند التسليم / لاحقًا","الدرج","شام كاش","الخزنة الخارجية","البنك"}));prepare(customer,"اسم العميل");prepare(phone,"رقم هاتف العميل");prepare(watch,"وصف الساعة / العطل / المطلوب");prepare(total,"المبلغ المتفق عليه");decorateRepairArea();Button save=a.findViewById(R.id.saveRepair);save.setText("✓ حفظ واستلام الصيانة");save.setMinHeight(dp(64));save.setTextSize(18);save.setTextColor(Color.WHITE);save.setBackgroundResource(R.drawable.alsafa_primary);save.setOnClickListener(v->save());}
 private void refreshParts(){partItems.clear();partItems.addAll(services.repairParts.search(partSearch.getText().toString(),20));java.util.ArrayList<String> labels=new java.util.ArrayList<>();for(RepairPartStore.SearchResult r:partItems)labels.add(r.name+" — المتاح "+r.quantity+(r.barcode==null||r.barcode.isEmpty()?"":" — "+r.barcode));if(labels.isEmpty())labels.add("بدون قطعة / لا توجد نتائج");partResults.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,labels));}
 private void prepare(EditText e,String hint){e.setHint(hint);e.setGravity(Gravity.END);e.setMinHeight(dp(56));e.setTextSize(16);e.setPadding(dp(14),dp(8),dp(14),dp(8));e.setBackgroundResource(R.drawable.alsafa_card);}
 private void decorateRepairArea(){View parent=(View)customer.getParent();if(!(parent instanceof LinearLayout))return;LinearLayout p=(LinearLayout)parent;int customerIndex=p.indexOfChild(customer);if(customerIndex<0)return;TextView heading=new TextView(a);heading.setText("استلام صيانة جديدة");heading.setTextSize(20);heading.setTextColor(Color.parseColor("#3E3429"));heading.setGravity(Gravity.END);heading.setPadding(dp(4),dp(18),dp(4),dp(2));TextView note=new TextView(a);note.setText("سجّل المبلغ المتفق عليه الآن. التحصيل والتسليم والحسم بعد المفاصلة تبقى خطوات مستقلة وواضحة.");note.setTextSize(13);note.setTextColor(Color.parseColor("#8A7B6C"));note.setGravity(Gravity.END);note.setPadding(dp(4),0,dp(4),dp(10));p.addView(heading,customerIndex);p.addView(note,customerIndex+1);styleSpinner(currency);styleSpinner(account);}
 private void styleSpinner(Spinner s){s.setMinimumHeight(dp(54));s.setPadding(dp(10),0,dp(10),0);s.setBackgroundResource(R.drawable.alsafa_card);}
 private void save(){try{String c=customer.getText().toString().trim(),ph=phone.getText().toString().trim(),w=watch.getText().toString().trim();if(c.isEmpty())throw new IllegalArgumentException("اسم العميل مطلوب");if(w.isEmpty())throw new IllegalArgumentException("وصف الساعة أو الصيانة مطلوب");String amountText=total.getText().toString().trim();if(amountText.isEmpty())throw new IllegalArgumentException("قيمة الصيانة المتفق عليها مطلوبة");double amount=Double.parseDouble(amountText);if(amount<0)throw new IllegalArgumentException("قيمة الصيانة غير صحيحة");String cur=AccountingChoices.codeAt(AccountingChoices.CURRENCY_CODES,currency.getSelectedItemPosition()),pay=paymentCode(account.getSelectedItemPosition());if("SHAM_CASH".equals(pay)&&"TRY".equals(cur))throw new IllegalArgumentException("شام كاش يقبل الدولار والليرة السورية فقط");String id=services.repairs.receive(c,ph,w,amount,cur,pay);if(!partItems.isEmpty()){int pp=partResults.getSelectedItemPosition();if(pp>=0&&pp<partItems.size()){int pq=Integer.parseInt(partQty.getText().toString().trim());if(pq<=0)throw new IllegalArgumentException("كمية قطعة الصيانة غير صحيحة");services.repairs.addPart(id,partItems.get(pp).partId,pq);}}Native4BackgroundSync.request(a);DeveloperDashboardPanelBinder.refreshActive();customer.setText("");phone.setText("");watch.setText("");partSearch.setText("");partItems.clear();partQty.setText("1");watch.setText("");total.setText("");account.setSelection(0);status.setText("✓ تم استلام الصيانة — المتفق عليه: "+fmt(amount)+" "+cur);showNextAction(id,amount,cur);}catch(Exception e){status.setText("لم تُحفظ الصيانة: "+msg(e));}}
 private void showNextAction(String id,double amount,String cur){new AlertDialog.Builder(a).setTitle("تم استلام الصيانة").setMessage("القيمة المتفق عليها: "+fmt(amount)+" "+cur+"\n\nعند التسليم تستطيع تحصيل كامل المبلغ أو جزء منه، أو تعديل السعر النهائي بعد مفاصلة العميل. فرق التخفيض يُسجل كحسم وليس كدفعة جزئية.").setNegativeButton("العودة للرئيسية",null).setPositiveButton("تحصيل / تسليم",(d,w)->delivery.show(id)).show();}
 private static String paymentCode(int p){if(p==1)return "CASH";if(p==2)return "SHAM_CASH";if(p==3)return "EXTERNAL";if(p==4)return "BANK";return "LATER";}
 private int dp(int v){return Math.round(v*a.getResources().getDisplayMetrics().density);}private static String fmt(double v){return String.format(java.util.Locale.US,"%.2f",v);}private static String msg(Exception e){return e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();}
}
